	('725bfd50-def6-48c8-90e2-fffbfe6e3298', 'celler-esdeveniments-teia', '00000000-0000-0000-0000-000000000001', 'Celler per a tastings i esdeveniments', 'Celler de pedra amb voltes originals del segle XIX. Temperatura natural de 15°C. Capacitat per a 40 persones, ideal per a tastings de vi, sopars de gala i presentacions exclusives.', 'room', 28000, 'EUR', 55.00, 'Plaça de l''Ajuntament', 'Teià', 'Teià', 'Catalunya', '0101000020E610000054742497FF90024011363CBD52BE4440', '{cellar,dimmable_light,stackable_chairs,audio}', '{}', false, 'active', '2026-05-04 20:17:27.827767+00', '2026-05-05 18:24:34.561827+00', 'hour', 'https://wa.me/34611223300?text=Hola%21+He+vist+el+celler+a+Somespai+i+m%27agradaria+saber-ne+m%C3%A9s.', 4.90, 16, NULL, NULL, NULL, NULL, 'email'),
	('e7efa81c-a7a1-4833-84f6-35046e9d84ce', 'spaces-diagonal', '00000000-0000-0000-0000-000000000001', 'Spaces — Avinguda Diagonal', 'Spaces Diagonal és un coworking premium a l''avinguda més emblemàtica de Barcelona. Recepció professional, sales de reunions d''alt nivell i serveis corporatius complets.', 'workspace', 32000, 'EUR', NULL, 'Avinguda Diagonal, 477', 'Les Corts', 'Barcelona', 'Catalunya', '0101000020E610000026E4839ECD2A01400AD7A3703DB24440', '{meeting_room,coffee,access_24h,reception}', '{}', false, 'active', '2026-05-04 20:17:27.827767+00', '2026-05-05 18:40:25.46523+00', 'month', 'https://www.spacesworks.com/es/barcelona/', 4.50, 51, NULL, NULL, NULL, 'https://somespai.net', 'web'),
	('94a46e0f-48e7-4663-aa87-ca030782bad8', 'estudi-creatiu-travessera', '00000000-0000-0000-0000-000000000001', 'Estudi creatiu Travessera', 'Estudi compartit amb fibra simètrica, escriptoris regulables i sala de reunions petita. Comunitat tranquil·la, ideal per a treball concentrat.', 'workspace', 26000, 'EUR', 38.00, 'Travessera de Gràcia', 'Vila de Gràcia', 'Barcelona', 'Catalunya', '0101000020E610000087A757CA32440140DE9387855AB34440', '{fiber,fixed_desk,coffee}', '{}', false, 'active', '2026-05-04 20:17:27.827767+00', '2026-05-04 20:17:27.827767+00', 'month', 'mailto:estudi.travessera@gmail.com', 4.50, 15, NULL, NULL, NULL, NULL, 'email'),
	('392507ac-e7d8-4335-8103-6a591ec60d8d', 'garatge-vallcarca', '00000000-0000-0000-0000-000000000001', 'Garatge convertit a Vallcarca', 'Garatge sec amb prestatgeries metàl·liques. Càmera de seguretat i accés 24/7 amb codi numèric.', 'storage', 8500, 'EUR', 16.00, 'Avinguda de Vallcarca', 'Vila de Gràcia', 'Barcelona', 'Catalunya', '0101000020E6100000014D840D4F2F0140789CA223B9B44440', '{access_24h,cameras,electricity}', '{}', false, 'active', '2026-05-04 20:17:27.827767+00', '2026-05-04 20:17:27.827767+00', 'month', 'https://wa.me/34677889900?text=Hola%21+He+vist+el+garatge+a+Somespai+i+m%27agradaria+saber-ne+m%C3%A9s.', 4.30, 6, NULL, NULL, NULL, NULL, 'email'),
	('25197e36-d8de-45b2-86de-ddd9b5cc809f', 'sala-reunions-sol', '00000000-0000-0000-0000-000000000001', 'Sala de reunions Plaça del Sol', 'Sala lluminosa per a 6 persones amb vistes a la plaça. Pissarra magnètica, projector i cafè artesà inclòs.', 'workspace', 14000, 'EUR', 18.00, 'Plaça del Sol', 'Vila de Gràcia', 'Barcelona', 'Catalunya', '0101000020E61000005BB1BFEC9E3C01405D6DC5FEB2B34440', '{whiteboard,projector,coffee}', '{}', false, 'active', '2026-05-04 20:17:27.827767+00', '2026-05-05 18:24:38.343791+00', 'hour', 'mailto:sala.placacasol@gmail.com', 4.90, 34, NULL, NULL, NULL, NULL, 'email'),
